mapper.select:
select p.PORTFOLIO_ID as portfolioId, p.PORTFOLIO_NAME as portfolioName, fp.FINPROD_ID as finprodId, fp.FINPROD_MARKET_ID as finprodMarketId, nvl(fp.FINPROD_ABBR,T.FINPROD_ABBR) as finprodAbbr, fp.FINPROD_TYPE2, nvl(fpt.TYPE_8,T.FINPROD_TYPE2) as type8, T.TRADE_DATE as tradeDate, T.PS as ps, T.INV_AIM as invAim, decode(fp.FINPROD_TYPE2, 'F01', T.SHARE_AMT * 100, T.SHARE_AMT) as amount, T.UNIT_CPRICE as tradePrice, T.UNIT_INT as accuir, T.TRADE_AMT as tradeAmt, T.MDATE as mdate, T.YIELD * 100 as yield, T.EXER_YIELD * 100 as exerYield, T.CCY as ccy FROM MOCK_PRODUCT_DEAL T left join PTL_PORTFOLIO p on T.PORTFOLIO_ID = p.PORTFOLIO_ID left join FIN_PRODUCT fp on T.FINPROD_ID = fp.FINPROD_ID left join FIN_PRODUCT_TYPE fpt on T.FINPROD_ID = fpt.FINPROD_ID
T.MOCK_ID = #{mockId}
order by order_id asc

select m.MOCK_ID mockId, m.PORTFOLIO_ID portfolioId, p.PORTFOLIO_NAME portfolioName, m.MDATE mdate, m.AGAIN_INVEST_RATE * 100 againInvestRate, m.FINAN_COST * 100 finanCost, m.MOCK_YIELD * 100 mockYield, m.MOCK_DATE mockDate from MOCK_TEST m inner join PTL_PORTFOLIO p on m.PORTFOLIO_ID = p.PORTFOLIO_ID
m.CREATE_USER = #{loginUserName}
and to_char(m.MOCK_DATE, 'yyyy-MM-dd') >= #{dataDateStart}
and to_char(m.MOCK_DATE, 'yyyy-MM-dd') <= #{dataDateEnd}
and m.PORTFOLIO_ID = #{portfolioId}
order by m.CREATE_TIME desc

mapper.delete:
delete from MOCK_TRADE_PRODUCT 
where FINPROD_ID in (
    select FINPROD_ID from
	MOCK_PRODUCT_DEAL WHERE MOCK_ID = #{mockId,jdbcType=VARCHAR}
)

mapper.select:
SELECT A.FINPROD_MARKET_ID id, A.FINPROD_ABBR text, A.FINPROD_ABBR, A.FINPROD_MARKET_ID, A.FINPROD_ID finprodId, A.CCY, B.TYPE_8, TO_CHAR(A.MDATE, 'yyyy-MM-dd') MDATE, A.IS_RIGHT isRight FROM FIN_PRODUCT A INNER JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID
( A.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.FINPROD_MARKET_ID = #{initValue}
AND B.TYPE_8 in
#{item}

 SELECT SUM(nvl(T.SHARE_AMT,0)) POSITION
  FROM MOCK_PRODUCT_DEAL T
WHERE T.FINPROD_ID = #{finprodId}
and T.portfolio_id = #{portfolioId}

and T.inv_Aim = #{invAim,jdbcType=VARCHAR}

and T.ps = #{PS_T01}
